import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type PriceComparisonChartProps = Record<string, any>;

const PriceComparisonChart: React.FC<PriceComparisonChartProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Pricing Comparison",
  normalPrice = 850,
  discountedPrice = 450,
  normalLabel = "Standard Rate",
  discountedLabel = "Discounted Rate",
  normalColor = "#ef4444", // Red
  discountedColor = "#22c55e", // Green
  yAxisMax = 1000,
  positionX = 0,
  positionY = 0,
  globalScale = 1,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Entrance Animation
  const globalEntrance = spring({
    frame,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  const chartScale = interpolate(globalEntrance, [0, 1], [0.9, globalScale]);
  const chartOpacity = interpolate(globalEntrance, [0, 1], [0, 1]);

  // Bar Animations
  const normalBarSpring = spring({
    frame: frame - 15,
    fps,
    config: { damping: 12, stiffness: 90 },
  });

  const discountedBarSpring = spring({
    frame: frame - 30,
    fps,
    config: { damping: 12, stiffness: 90 },
  });

  // Chart Dimensions & Layout
  const chartWidth = 1200;
  const chartHeight = 600;
  
  const normalHeightPct = Math.min(normalPrice / yAxisMax, 1);
  const discountedHeightPct = Math.min(discountedPrice / yAxisMax, 1);

  const currentNormalPrice = Math.round(normalPrice * normalBarSpring);
  const currentDiscountedPrice = Math.round(discountedPrice * discountedBarSpring);

  // Y-Axis Markers (0, 25%, 50%, 75%, 100%)
  const yAxisMarkers = [0, 0.25, 0.5, 0.75, 1];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `translate(${positionX}px, ${positionY}px) scale(${chartScale})`,
          opacity: chartOpacity,
        }}
      >
        <div
          style={{
            position: "relative",
            width: chartWidth,
            height: chartHeight,
            display: "flex",
            flexDirection: "column",
          }}
        >
          {/* Title */}
          <div
            style={{
              position: "absolute",
              top: -120,
              left: 0,
              color: "#ffffff",
              fontSize: 64,
              fontWeight: 700,
              letterSpacing: "-0.02em",
              opacity: interpolate(frame, [5, 20], [0, 1], { extrapolateRight: "clamp" }),
              transform: `translateY(${interpolate(frame, [5, 20], [20, 0], { extrapolateRight: "clamp" })}px)`,
            }}
          >
            {title}
          </div>

          {/* Chart Area Background / Grid */}
          <div style={{ position: "absolute", top: 0, left: 0, right: 0, bottom: 0 }}>
            {yAxisMarkers.map((marker, idx) => {
              const markerValue = Math.round(yAxisMax * marker);
              const bottomPosition = `${marker * 100}%`;
              const lineSpring = spring({ frame: frame - (idx * 3), fps, config: { damping: 12 } });
              
              return (
                <div
                  key={`grid-${idx}`}
                  style={{
                    position: "absolute",
                    bottom: bottomPosition,
                    left: 0,
                    width: "100%",
                    display: "flex",
                    alignItems: "center",
                    transform: `translateY(50%)`,
                  }}
                >
                  <span
                    style={{
                      width: 100,
                      textAlign: "right",
                      paddingRight: 20,
                      color: "#888888",
                      fontSize: 24,
                      fontWeight: 500,
                      opacity: lineSpring,
                    }}
                  >
                    ${markerValue}
                  </span>
                  <div
                    style={{
                      flex: 1,
                      height: 2,
                      backgroundColor: "rgba(255, 255, 255, 0.1)",
                      transformOrigin: "left center",
                      transform: `scaleX(${lineSpring})`,
                      opacity: lineSpring,
                    }}
                  />
                </div>
              );
            })}
          </div>

          {/* Bars Container */}
          <div
            style={{
              position: "absolute",
              bottom: 0,
              left: 120, // Offset for Y-axis labels
              right: 0,
              height: "100%",
              display: "flex",
              justifyContent: "space-evenly",
              alignItems: "flex-end",
            }}
          >
            {/* Normal Price Bar */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                width: 280,
              }}
            >
              <span
                style={{
                  color: normalColor,
                  fontSize: 48,
                  fontWeight: 800,
                  marginBottom: 20,
                  opacity: normalBarSpring,
                  transform: `translateY(${interpolate(normalBarSpring, [0, 1], [20, 0])}px)`,
                }}
              >
                ${currentNormalPrice}
              </span>
              <div
                style={{
                  width: "100%",
                  height: chartHeight * normalHeightPct * normalBarSpring,
                  backgroundColor: normalColor,
                  borderRadius: "16px 16px 0 0",
                  boxShadow: `0 0 40px ${normalColor}40`,
                }}
              />
              <span
                style={{
                  position: "absolute",
                  bottom: -60,
                  color: "#ffffff",
                  fontSize: 28,
                  fontWeight: 600,
                  opacity: interpolate(frame, [25, 40], [0, 1], { extrapolateRight: "clamp" }),
                }}
              >
                {normalLabel}
              </span>
            </div>

            {/* Discounted Price Bar */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                width: 280,
              }}
            >
              <span
                style={{
                  color: discountedColor,
                  fontSize: 48,
                  fontWeight: 800,
                  marginBottom: 20,
                  opacity: discountedBarSpring,
                  transform: `translateY(${interpolate(discountedBarSpring, [0, 1], [20, 0])}px)`,
                }}
              >
                ${currentDiscountedPrice}
              </span>
              <div
                style={{
                  width: "100%",
                  height: chartHeight * discountedHeightPct * discountedBarSpring,
                  backgroundColor: discountedColor,
                  borderRadius: "16px 16px 0 0",
                  boxShadow: `0 0 40px ${discountedColor}40`,
                }}
              />
              <span
                style={{
                  position: "absolute",
                  bottom: -60,
                  color: "#ffffff",
                  fontSize: 28,
                  fontWeight: 600,
                  opacity: interpolate(frame, [40, 55], [0, 1], { extrapolateRight: "clamp" }),
                }}
              >
                {discountedLabel}
              </span>
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default PriceComparisonChart;